import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { PieChart, Pie, Cell, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from 'recharts';
import { FaBug, FaSpinner, FaCheckCircle, FaTimesCircle, FaUsers, FaPlus, FaList, FaUserShield } from 'react-icons/fa';
import { getIssueCountByStatus, getIssues } from '../../api/issues';
import { getAllUsers } from '../../api/users';
import DashboardLayout from '../../components/layout/DashboardLayout';

const COLORS = {
  OPEN: '#3b82f6',
  IN_PROGRESS: '#f59e0b',
  RESOLVED: '#10b981',
  CLOSED: '#6b7280',
};

const STATUS_ICONS = {
  OPEN: <FaBug className="text-blue-500" size={20} />,
  IN_PROGRESS: <FaSpinner className="text-yellow-500" size={20} />,
  RESOLVED: <FaCheckCircle className="text-green-500" size={20} />,
  CLOSED: <FaTimesCircle className="text-gray-500" size={20} />,
};

const AdminDashboard = ({ sidebarItems }) => {
  const navigate = useNavigate();
  const [statusCounts, setStatusCounts] = useState([]);
  const [recentIssues, setRecentIssues] = useState([]);
  const [totalUsers, setTotalUsers] = useState(0);
  const [totalIssues, setTotalIssues] = useState(0);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      const [counts, issuesRes, users] = await Promise.all([
        getIssueCountByStatus(),
        getIssues({ page: 0, size: 5, sort: 'createdAt,desc' }),
        getAllUsers(),
      ]);

      const countsData = counts || [];
      setStatusCounts(countsData);
      setTotalIssues(countsData.reduce((sum, c) => sum + c.count, 0));
      setRecentIssues(issuesRes.content || []);
      setTotalUsers(Array.isArray(users) ? users.length : 0);
    } catch (error) {
      console.error('Failed to fetch dashboard data:', error);
    } finally {
      setLoading(false);
    }
  };

  const pieData = statusCounts.map(sc => ({
    name: sc.status.replace('_', ' '),
    value: sc.count,
    color: COLORS[sc.status] || '#94a3b8',
  }));

  const barData = statusCounts.map(sc => ({
    name: sc.status.replace('_', ' '),
    count: sc.count,
    fill: COLORS[sc.status] || '#94a3b8',
  }));

  const getStatusBadge = (status) => {
    const colors = {
      OPEN: 'bg-blue-100 text-blue-700',
      IN_PROGRESS: 'bg-yellow-100 text-yellow-700',
      RESOLVED: 'bg-green-100 text-green-700',
      CLOSED: 'bg-gray-100 text-gray-700',
    };
    return (
      <span className={`px-2 py-0.5 rounded-full text-xs font-semibold ${colors[status] || 'bg-gray-100'}`}>
        {status?.replace('_', ' ')}
      </span>
    );
  };

  if (loading) {
    return (
      <DashboardLayout userRole="ADMIN" sidebarItems={sidebarItems}>
        <div className="flex items-center justify-center h-64">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#3da58a]"></div>
        </div>
      </DashboardLayout>
    );
  }

  return (
    <DashboardLayout userRole="ADMIN" sidebarItems={sidebarItems}>
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between mb-6">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Admin Dashboard</h1>
          <p className="text-sm text-gray-500 mt-1">Complete system overview</p>
        </div>
        <div className="flex gap-2 mt-3 sm:mt-0">
          <button
            onClick={() => navigate('/admin/issues/new')}
            className="flex items-center gap-2 px-4 py-2 bg-[#3da58a] text-white rounded-lg text-sm font-semibold hover:bg-[#2d8a72] transition-colors shadow-md"
          >
            <FaPlus /> New Issue
          </button>
          <button
            onClick={() => navigate('/admin/users')}
            className="flex items-center gap-2 px-4 py-2 bg-[#1a365d] text-white rounded-lg text-sm font-semibold hover:bg-[#13294b] transition-colors shadow-md"
          >
            <FaUsers /> Users
          </button>
        </div>
      </div>

      {/* Stat Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-5 gap-4 mb-6">
        {/* Total Issues */}
        <div className="bg-white rounded-2xl shadow-md p-5 border border-gray-100 hover:shadow-lg transition-shadow">
          <div className="flex items-center justify-between mb-3">
            <span className="text-2xl"><FaList className="text-indigo-500" /></span>
            <span className="text-3xl font-bold text-gray-800">{totalIssues}</span>
          </div>
          <p className="text-sm font-medium text-gray-500">Total Issues</p>
        </div>

        {['OPEN', 'IN_PROGRESS', 'RESOLVED', 'CLOSED'].map(status => {
          const count = statusCounts.find(s => s.status === status)?.count || 0;
          return (
            <div key={status} className="bg-white rounded-2xl shadow-md p-5 border border-gray-100 hover:shadow-lg transition-shadow">
              <div className="flex items-center justify-between mb-3">
                <span className="text-2xl">{STATUS_ICONS[status]}</span>
                <span className="text-3xl font-bold text-gray-800">{count}</span>
              </div>
              <p className="text-sm font-medium text-gray-500">{status.replace('_', ' ')}</p>
            </div>
          );
        })}
      </div>

      {/* Users Card */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-6">
        <div
          onClick={() => navigate('/admin/users')}
          className="bg-gradient-to-r from-[#1a365d] to-[#2a4a7f] rounded-2xl shadow-lg p-6 text-white cursor-pointer hover:shadow-xl transition-shadow"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-white/70">Total Users</p>
              <p className="text-4xl font-bold mt-1">{totalUsers}</p>
            </div>
            <FaUserShield className="text-white/30" size={48} />
          </div>
          <p className="text-xs text-white/50 mt-3">Click to manage users →</p>
        </div>

        {/* Pie Chart */}
        <div className="bg-white rounded-2xl shadow-md p-6 border border-gray-100 lg:col-span-2">
          <h3 className="text-lg font-bold text-gray-800 mb-4">Issue Distribution</h3>
          {totalIssues === 0 ? (
            <p className="text-center text-gray-400 py-8">No issues yet</p>
          ) : (
            <ResponsiveContainer width="100%" height={240}>
              <PieChart>
                <Pie data={pieData} cx="50%" cy="50%" innerRadius={50} outerRadius={90} paddingAngle={4} dataKey="value" label={({ name, value }) => `${name}: ${value}`}>
                  {pieData.map((entry, i) => (
                    <Cell key={i} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend />
              </PieChart>
            </ResponsiveContainer>
          )}
        </div>
      </div>

      {/* Bar Chart + Recent Issues */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Bar Chart */}
        <div className="bg-white rounded-2xl shadow-md p-6 border border-gray-100">
          <h3 className="text-lg font-bold text-gray-800 mb-4">Issues by Status</h3>
          {totalIssues === 0 ? (
            <p className="text-center text-gray-400 py-8">No issues yet</p>
          ) : (
            <ResponsiveContainer width="100%" height={280}>
              <BarChart data={barData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                <XAxis dataKey="name" tick={{ fontSize: 12 }} />
                <YAxis tick={{ fontSize: 12 }} />
                <Tooltip />
                <Bar dataKey="count" radius={[8, 8, 0, 0]}>
                  {barData.map((entry, i) => (
                    <Cell key={i} fill={entry.fill} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          )}
        </div>

        {/* Recent Issues */}
        <div className="bg-white rounded-2xl shadow-md p-6 border border-gray-100">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-bold text-gray-800">Recent Issues</h3>
            <button onClick={() => navigate('/admin/issues')} className="text-sm text-[#1a365d] font-semibold hover:underline">
              View All →
            </button>
          </div>
          {recentIssues.length === 0 ? (
            <p className="text-center text-gray-400 py-6">No issues found</p>
          ) : (
            <div className="space-y-3">
              {recentIssues.map(issue => (
                <div
                  key={issue.id}
                  onClick={() => navigate(`/admin/issues/${issue.id}`)}
                  className="flex items-center justify-between p-3 rounded-xl hover:bg-gray-50 cursor-pointer transition-colors border border-gray-100"
                >
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-semibold text-gray-800 truncate">{issue.title}</p>
                    <p className="text-xs text-gray-400 mt-0.5">
                      {issue.createdBy} · {issue.createdAt ? new Date(issue.createdAt).toLocaleDateString() : ''}
                    </p>
                  </div>
                  <div className="ml-3">{getStatusBadge(issue.status)}</div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </DashboardLayout>
  );
};

export default AdminDashboard;
