import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { PieChart, Pie, Cell, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from 'recharts';
import { FaBug, FaSpinner, FaCheckCircle, FaTimesCircle, FaPlus, FaList } from 'react-icons/fa';
import { getIssueCountByStatus, getIssues } from '../../api/issues';
import DashboardLayout from '../../components/layout/DashboardLayout';
import { getUserRole } from '../../api/auth';

const COLORS = {
  OPEN: '#3b82f6',
  IN_PROGRESS: '#f59e0b',
  RESOLVED: '#10b981',
  CLOSED: '#6b7280',
};

const STATUS_ICONS = {
  OPEN: <FaBug className="text-blue-500" />,
  IN_PROGRESS: <FaSpinner className="text-yellow-500" />,
  RESOLVED: <FaCheckCircle className="text-green-500" />,
  CLOSED: <FaTimesCircle className="text-gray-500" />,
};

const UserDashboard = ({ sidebarItems }) => {
  const navigate = useNavigate();
  const [statusCounts, setStatusCounts] = useState([]);
  const [recentIssues, setRecentIssues] = useState([]);
  const [loading, setLoading] = useState(true);
  const [totalIssues, setTotalIssues] = useState(0);
  const userRole = getUserRole();

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      const [counts, issuesRes] = await Promise.all([
        getIssueCountByStatus(),
        getIssues({ page: 0, size: 5, sort: 'createdAt,desc' }),
      ]);

      // counts is an array of { count, status }
      const countsData = counts || [];
      setStatusCounts(countsData);
      setTotalIssues(countsData.reduce((sum, c) => sum + c.count, 0));

      // issuesRes is a Spring Page object
      setRecentIssues(issuesRes.content || []);
    } catch (error) {
      console.error('Failed to fetch dashboard data:', error);
    } finally {
      setLoading(false);
    }
  };

  const pieData = statusCounts.map(sc => ({
    name: sc.status.replace('_', ' '),
    value: sc.count,
    color: COLORS[sc.status] || '#94a3b8',
  }));

  const barData = statusCounts.map(sc => ({
    name: sc.status.replace('_', ' '),
    count: sc.count,
    fill: COLORS[sc.status] || '#94a3b8',
  }));

  const getStatusBadge = (status) => {
    const colors = {
      OPEN: 'bg-blue-100 text-blue-700',
      IN_PROGRESS: 'bg-yellow-100 text-yellow-700',
      RESOLVED: 'bg-green-100 text-green-700',
      CLOSED: 'bg-gray-100 text-gray-700',
    };
    return (
      <span className={`px-2 py-0.5 rounded-full text-xs font-semibold ${colors[status] || 'bg-gray-100 text-gray-700'}`}>
        {status?.replace('_', ' ')}
      </span>
    );
  };

  if (loading) {
    return (
      <DashboardLayout userRole={userRole} sidebarItems={sidebarItems}>
        <div className="flex items-center justify-center h-64">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#3da58a]"></div>
        </div>
      </DashboardLayout>
    );
  }

  return (
    <DashboardLayout userRole={userRole} sidebarItems={sidebarItems}>
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between mb-6">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Dashboard</h1>
          <p className="text-sm text-gray-500 mt-1">Overview of your issues</p>
        </div>
        <div className="flex gap-2 mt-3 sm:mt-0">
          <button
            onClick={() => navigate('/issues/new')}
            className="flex items-center gap-2 px-4 py-2 bg-[#3da58a] text-white rounded-lg text-sm font-semibold hover:bg-[#2d8a72] transition-colors shadow-md"
          >
            <FaPlus /> New Issue
          </button>
          <button
            onClick={() => navigate('/issues')}
            className="flex items-center gap-2 px-4 py-2 bg-[#1a365d] text-white rounded-lg text-sm font-semibold hover:bg-[#13294b] transition-colors shadow-md"
          >
            <FaList /> All Issues
          </button>
        </div>
      </div>

      {/* Stat Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
        {['OPEN', 'IN_PROGRESS', 'RESOLVED', 'CLOSED'].map(status => {
          const count = statusCounts.find(s => s.status === status)?.count || 0;
          return (
            <div key={status} className="bg-white rounded-2xl shadow-md p-5 border border-gray-100 hover:shadow-lg transition-shadow">
              <div className="flex items-center justify-between mb-3">
                <span className="text-2xl">{STATUS_ICONS[status]}</span>
                <span className="text-3xl font-bold text-gray-800">{count}</span>
              </div>
              <p className="text-sm font-medium text-gray-500">{status.replace('_', ' ')}</p>
            </div>
          );
        })}
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
        {/* Pie Chart */}
        <div className="bg-white rounded-2xl shadow-md p-6 border border-gray-100">
          <h3 className="text-lg font-bold text-gray-800 mb-4">Issue Distribution</h3>
          {totalIssues === 0 ? (
            <p className="text-center text-gray-400 py-10">No issues yet</p>
          ) : (
            <ResponsiveContainer width="100%" height={280}>
              <PieChart>
                <Pie
                  data={pieData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={100}
                  paddingAngle={4}
                  dataKey="value"
                  label={({ name, value }) => `${name}: ${value}`}
                >
                  {pieData.map((entry, index) => (
                    <Cell key={index} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend />
              </PieChart>
            </ResponsiveContainer>
          )}
        </div>

        {/* Bar Chart */}
        <div className="bg-white rounded-2xl shadow-md p-6 border border-gray-100">
          <h3 className="text-lg font-bold text-gray-800 mb-4">Issues by Status</h3>
          {totalIssues === 0 ? (
            <p className="text-center text-gray-400 py-10">No issues yet</p>
          ) : (
            <ResponsiveContainer width="100%" height={280}>
              <BarChart data={barData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                <XAxis dataKey="name" tick={{ fontSize: 12 }} />
                <YAxis tick={{ fontSize: 12 }} />
                <Tooltip />
                <Bar dataKey="count" radius={[8, 8, 0, 0]}>
                  {barData.map((entry, index) => (
                    <Cell key={index} fill={entry.fill} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          )}
        </div>
      </div>

      {/* Recent Issues */}
      <div className="bg-white rounded-2xl shadow-md p-6 border border-gray-100">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-bold text-gray-800">Recent Issues</h3>
          <button
            onClick={() => navigate('/issues')}
            className="text-sm text-[#1a365d] font-semibold hover:underline"
          >
            View All →
          </button>
        </div>
        {recentIssues.length === 0 ? (
          <p className="text-center text-gray-400 py-6">No issues found. Create your first issue!</p>
        ) : (
          <div className="space-y-3">
            {recentIssues.map(issue => (
              <div
                key={issue.id}
                onClick={() => navigate(`/issues/${issue.id}`)}
                className="flex items-center justify-between p-3 rounded-xl hover:bg-gray-50 cursor-pointer transition-colors border border-gray-100"
              >
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-semibold text-gray-800 truncate">{issue.title}</p>
                  <p className="text-xs text-gray-400 mt-0.5">
                    {issue.createdBy} · {issue.createdAt ? new Date(issue.createdAt).toLocaleDateString() : ''}
                  </p>
                </div>
                <div className="flex items-center gap-2 ml-3">
                  {getStatusBadge(issue.status)}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </DashboardLayout>
  );
};

export default UserDashboard;
