import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { FaEnvelope, FaLock, FaBug } from 'react-icons/fa';
import * as Yup from 'yup';
import BasicForm from '../../components/BasicForm';
import CustomTextField from '../../components/CustomTextField';
import CustomButton from '../../components/CustomButton';
import BasicAlertBox from '../../components/BasicAlertBox';
import { registerUser } from '../../api/auth';

const registerSchema = Yup.object().shape({
  email: Yup.string().email('Invalid email').required('Email is required'),
  password: Yup.string().min(4, 'Password must be at least 4 characters').required('Password is required'),
  confirmPassword: Yup.string()
    .oneOf([Yup.ref('password'), null], 'Passwords must match')
    .required('Confirm password is required'),
});

const RegisterPage = () => {
  const navigate = useNavigate();
  const [alert, setAlert] = useState({ open: false, message: '', type: 'info', title: '' });

  const handleRegister = async (values, { setSubmitting }) => {
    try {
      await registerUser(values.email, values.password);
      setAlert({
        open: true,
        message: 'Account created successfully! Please login.',
        type: 'success',
        title: 'Registration Successful',
      });
      setTimeout(() => navigate('/login'), 1500);
    } catch (error) {
      const msg = error.response?.data?.message || error.response?.data?.error || 'Registration failed. Please try again.';
      setAlert({ open: true, message: msg, type: 'danger', title: 'Registration Failed' });
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-[#0f172a] via-[#1e293b] to-[#1a365d] p-4">
      <div className="w-full max-w-md">
        {/* Logo */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-16 h-16 bg-[#3da58a] rounded-2xl shadow-2xl mb-4">
            <FaBug className="h-8 w-8 text-white" />
          </div>
          <h1 className="text-3xl font-bold text-white">Create Account</h1>
          <p className="text-gray-400 text-sm mt-1">Join the Issue Tracker platform</p>
        </div>

        {/* Form Card */}
        <div className="bg-white rounded-2xl shadow-2xl p-8">
          <BasicForm
            initialValues={{ email: '', password: '', confirmPassword: '' }}
            validationSchema={registerSchema}
            onSubmit={handleRegister}
          >
            {({ errors, touched, handleChange, values, isSubmitting }) => (
              <>
                <CustomTextField
                  name="email"
                  label="Email Address"
                  type="email"
                  value={values.email}
                  onChange={handleChange}
                  error={errors.email}
                  touched={touched.email}
                  icon={FaEnvelope}
                />
                <CustomTextField
                  name="password"
                  label="Password"
                  type="password"
                  value={values.password}
                  onChange={handleChange}
                  error={errors.password}
                  touched={touched.password}
                  icon={FaLock}
                />
                <CustomTextField
                  name="confirmPassword"
                  label="Confirm Password"
                  type="password"
                  value={values.confirmPassword}
                  onChange={handleChange}
                  error={errors.confirmPassword}
                  touched={touched.confirmPassword}
                  icon={FaLock}
                />
                <CustomButton type="submit" disabled={isSubmitting}>
                  {isSubmitting ? 'Creating Account...' : 'Create Account'}
                </CustomButton>
              </>
            )}
          </BasicForm>

          <p className="text-center text-sm text-gray-500 mt-4">
            Already have an account?{' '}
            <Link to="/login" className="text-[#1a365d] font-semibold hover:underline">
              Sign In
            </Link>
          </p>
        </div>
      </div>

      <BasicAlertBox
        open={alert.open}
        title={alert.title}
        message={alert.message}
        type={alert.type}
        onConfirm={() => setAlert({ ...alert, open: false })}
        autoClose={alert.type === 'success'}
      />
    </div>
  );
};

export default RegisterPage;
