import api from './axiosConfig';

// ─── Auth ───
export const registerUser = async (email, password) => {
  const response = await api.post('/auth/register', { email, password });
  return response.data;
};

export const loginUser = async (email, password) => {
  const response = await api.post('/auth/login', { email, password });
  return response.data;
};

// ─── Helpers ───
const getStorage = () => {
  const usePersistent = sessionStorage.getItem('usePersistentStorage');
  return usePersistent === 'true' ? localStorage : sessionStorage;
};

export const saveAuthData = (tokenResponse, rememberMe = false) => {
  if (rememberMe) {
    sessionStorage.setItem('usePersistentStorage', 'true');
    localStorage.setItem('rememberMe', 'true');
  } else {
    sessionStorage.removeItem('usePersistentStorage');
  }

  const storage = getStorage();
  storage.setItem('authToken', tokenResponse.token);
  storage.setItem(
    'userData',
    JSON.stringify({ role: tokenResponse.role })
  );
};

export const isAuthenticated = () => {
  const storage = getStorage();
  return !!storage.getItem('authToken');
};

export const getUserData = () => {
  const storage = getStorage();
  const data = storage.getItem('userData');
  return data ? JSON.parse(data) : null;
};

export const getUserRole = () => {
  const data = getUserData();
  return data?.role || null;
};

export const logout = () => {
  const storage = getStorage();
  storage.removeItem('authToken');
  storage.removeItem('userData');
  sessionStorage.removeItem('usePersistentStorage');
  localStorage.removeItem('rememberedUser');
  localStorage.removeItem('rememberMe');
  localStorage.setItem('logout', 'true');
  window.location.href = '/login';
};
