import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { FaEnvelope, FaLock, FaBug } from 'react-icons/fa';
import * as Yup from 'yup';
import BasicForm from '../../components/BasicForm';
import CustomTextField from '../../components/CustomTextField';
import CustomButton from '../../components/CustomButton';
import BasicCheckbox from '../../components/BasicCheckbox';
import BasicAlertBox from '../../components/BasicAlertBox';
import { loginUser, saveAuthData } from '../../api/auth';

const loginSchema = Yup.object().shape({
  email: Yup.string().email('Invalid email').required('Email is required'),
  password: Yup.string().required('Password is required'),
});

const LoginPage = () => {
  const navigate = useNavigate();
  const [rememberMe, setRememberMe] = useState(false);
  const [alert, setAlert] = useState({ open: false, message: '', type: 'info', title: '' });

  const handleLogin = async (values, { setSubmitting }) => {
    try {
      const response = await loginUser(values.email, values.password);
      saveAuthData(response, rememberMe);

      setAlert({
        open: true,
        message: 'Login successful! Redirecting...',
        type: 'success',
        title: 'Welcome Back',
      });

      setTimeout(() => {
        const role = response.role;
        if (role === 'ADMIN') {
          navigate('/admin/dashboard');
        } else {
          navigate('/dashboard');
        }
      }, 800);
    } catch (error) {
      const msg = error.response?.data?.message || error.response?.data?.error || 'Login failed. Please check your credentials.';
      setAlert({ open: true, message: msg, type: 'danger', title: 'Login Failed' });
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-[#0f172a] via-[#1e293b] to-[#1a365d] p-4">
      <div className="w-full max-w-md">
        {/* Logo */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-16 h-16 bg-[#3da58a] rounded-2xl shadow-2xl mb-4">
            <FaBug className="h-8 w-8 text-white" />
          </div>
          <h1 className="text-3xl font-bold text-white">Issue Tracker</h1>
          <p className="text-gray-400 text-sm mt-1">Sign in to your account</p>
        </div>

        {/* Form Card */}
        <div className="bg-white rounded-2xl shadow-2xl p-8">
          <BasicForm
            initialValues={{ email: '', password: '' }}
            validationSchema={loginSchema}
            onSubmit={handleLogin}
          >
            {({ errors, touched, handleChange, values, isSubmitting }) => (
              <>
                <CustomTextField
                  name="email"
                  label="Email Address"
                  type="email"
                  value={values.email}
                  onChange={handleChange}
                  error={errors.email}
                  touched={touched.email}
                  icon={FaEnvelope}
                />
                <CustomTextField
                  name="password"
                  label="Password"
                  type="password"
                  value={values.password}
                  onChange={handleChange}
                  error={errors.password}
                  touched={touched.password}
                  icon={FaLock}
                />
                <BasicCheckbox
                  name="rememberMe"
                  checked={rememberMe}
                  onChange={(e) => setRememberMe(e.target.checked)}
                  label="Remember me"
                />
                <CustomButton type="submit" disabled={isSubmitting}>
                  {isSubmitting ? 'Signing in...' : 'Sign In'}
                </CustomButton>
              </>
            )}
          </BasicForm>

          <p className="text-center text-sm text-gray-500 mt-4">
            Don't have an account?{' '}
            <Link to="/register" className="text-[#1a365d] font-semibold hover:underline">
              Register
            </Link>
          </p>
        </div>
      </div>

      <BasicAlertBox
        open={alert.open}
        title={alert.title}
        message={alert.message}
        type={alert.type}
        onConfirm={() => setAlert({ ...alert, open: false })}
        autoClose={alert.type === 'success'}
      />
    </div>
  );
};

export default LoginPage;
